  shipments ecommerce_platform_shipments[]
  sellerApprovalRequests ecommerce_platform_seller_approval_requests[]
  administratorPromotionRequestOfSeller ecommerce_platform_administrator_promotion_request_of_sellers?

  //----
  // INDEXES
  //----
  @@unique([email])
}

