  /// request was processed. It remains null while the request is in pending
  /// status, allowing tracking of review response times.
  reviewed_at DateTime? @db.Timestamptz

  /// Timestamp of when the requester submitted this administrator promotion
  /// application.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the latest modification to this request record, updated when
  /// the status changes during review.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  reviewedByAdmin ecommerce_platform_admins? @relation(fields: [reviewed_by_admin_id], references: [id], onDelete: Cascade, map: "ecommerce_platform_administrator_promotion_requests_re_53fd73ab")

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  customerPromotionSubtype ecommerce_platform_administrator_promotion_request_of_customers?
  sellerSubtype ecommerce_platform_administrator_promotion_request_of_sellers?

  //----
