  // spellchecker: ignore-next-line
  @@index([reviewed_by_admin_id], map: "ecommerce_platform_administrator_promotion_requests_re_5a1ff9c1")
  // spellchecker: ignore-next-line
  @@index([actor_type], map: "ecommerce_platform_administrator_promotion_requests_ac_6904ca5e")
