  //----
  // spellchecker: ignore-next-line
  product ecommerce_platform_products @relation(fields: [ecommerce_platform_product_id], references: [id], onDelete: Cascade, map: "ecommerce_platform_product_variants_ecommerce_platform_b649a16f")

  //----
