    firstVariant.sku_code,
    skuCode,
  );
  // 5. Seller attempts duplicate SKU creation - expect 409 Conflict rejection
  await TestValidator.httpError(
    "duplicate SKU code rejected with 409 Conflict",
    409,
    async () => {
      const duplicateBody = {
        skuCode,
