    await generate_random_ecommerce_platform_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: { productId, variantId },
        body: {
          quantity_delta,
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        },
      },
    );
