  // Step 7: Admin retrieves the specific inventory record
  const inventoryId = inventory.id;
  const retrieved =
    await api.functional.ecommercePlatform.admin.products.variants.inventory.at(
      adminConnection,
      {
        productId,
        variantId,
        inventoryId,
      },
    );
