  await TestValidator.httpError(
    "update non-existent cart item returns 404 not found",
    404,
    async () => {
      await api.functional.ecommercePlatform.customer.cart_items.update(
        customerConnection,
        {
          cartItemId: nonExistentCartItemId,
          body: updateBody,
        },
      );
