  const futureDate = new Date(now.getTime() + 86400000 * 30);
  const dateRangeResponse =
    await api.functional.ecommercePlatform.customer.orders.index(
      customerConnection,
      {
        body: {
          created_at_from: now.toISOString(),
          created_at_to: futureDate.toISOString(),
