    await api.functional.ecommercePlatform.customer.orders.index(
      customerConnection,
      {
        body: {
          search: RandomGenerator.alphabets(4),
          status: "shipped",
          created_at_from: new Date(now.getTime() - 86400000 * 7).toISOString(),
          created_at_to: futureDate.toISOString(),
