/**
 * Test rejection when seller attempts to re-add already-shipped items to a different shipment.
 *
 * Validates that order items that have already been bundled into a shipment and transitioned to 'shipped' status cannot be added to another shipment. Once items are included in a shipment, they transition from 'paid' to 'shipped' status and become permanently associated with that shipment package. The system enforces single-shipment assignment and status-based validation.
 *
 * The test covers two rejection conditions simultaneously: items must be in 'paid' status to be added to a shipment, and each order item can only belong to one shipment package.
 *
 * 1. Admin joins and creates a product category for classification.
 * 2. Seller joins and creates their product with a variant for ordering.
 * 3. Customer joins, creates shipping address, and places first order (items in 'paid' status).
 * 4. Seller creates first shipment bundling those order items (items transition to 'shipped').
 * 5. Customer places second order for the same product variant (new items in 'paid' status).
 * 6. Seller creates second shipment with items from the second order.
 * 7. Seller attempts to add already-shipped items from first order to the second shipment.
 * 8. System rejects because items are already in 'shipped' status and assigned to another shipment.
 */
export async function test_api_shipment_already_shipped_items_rejection(
  connection: api.IConnection,
): Promise<void> {
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(16);
  // 1. Admin joins and creates category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: { email: adminEmail, password: adminPassword },
  });
  const category =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 2. Seller joins, creates product with variant
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: { email: sellerEmail, password: sellerPassword },
  });
  const product =
    await generate_random_ecommerce_platform_seller_products_create(
      sellerConnection,
      { body: { category_id: category.id } },
    );
  typia.assert(product);
  const variant =
    await generate_random_ecommerce_platform_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  // 3. Customer joins and creates address
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: { email: customerEmail, password: customerPassword },
  });
  const address =
    await generate_random_ecommerce_platform_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 4. Customer places first order
  const order1Items = [
    {
      ecommerce_platform_product_variant_id: variant.id,
      quantity: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
      price: 1000 satisfies number & tags.Minimum<0>,
    },
  ] satisfies IEcommercePlatformOrderItem.ICreate[] & tags.MinItems<1>;
  const order1Body = {
    items: order1Items,
    shipping_address_id: address.id,
  } satisfies IEcommercePlatformOrder.ICreate;
  const order1 = await api.functional.ecommercePlatform.customer.orders.create(
    customerConnection,
    { body: order1Body },
  );
  typia.assert(order1);
  // 5. Seller creates first shipment (items transition to 'shipped')
  const firstShipmentBody = {
    carrierName: "TestCarrierOne",
    trackingNumber: "TRACK-FIRST-001",
    orderItemIds: order1.items.map((i) => i.id),
  } satisfies IEcommercePlatformShipment.ICreate;
  const shipment1 =
    await api.functional.ecommercePlatform.seller.shipments.create(
      sellerConnection,
      { body: firstShipmentBody },
    );
  typia.assert(shipment1);
  // 6. Customer places second order
  const order2Items = [
    {
      ecommerce_platform_product_variant_id: variant.id,
      quantity: 1 satisfies number & tags.Type<"int32"> & tags.Minimum<1>,
      price: 1000 satisfies number & tags.Minimum<0>,
    },
  ] satisfies IEcommercePlatformOrderItem.ICreate[] & tags.MinItems<1>;
  const order2Body = {
    items: order2Items,
    shipping_address_id: address.id,
  } satisfies IEcommercePlatformOrder.ICreate;
  const order2 = await api.functional.ecommercePlatform.customer.orders.create(
    customerConnection,
    { body: order2Body },
  );
  typia.assert(order2);
  // 7. Seller creates second shipment with items from second order
  const secondShipmentBody = {
    carrierName: "TestCarrierTwo",
    trackingNumber: "TRACK-SECOND-002",
    orderItemIds: order2.items.map((i) => i.id),
  } satisfies IEcommercePlatformShipment.ICreate;
  const shipment2 =
    await api.functional.ecommercePlatform.seller.shipments.create(
      sellerConnection,
      { body: secondShipmentBody },
    );
  typia.assert(shipment2);
  // 8. Attempt to add already-shipped items from order1 to shipment2 → REJECT
  const alreadyShippedItemIds = order1.items.map((i) => i.id);
  const addItemsBody = {
    order_item_ids: alreadyShippedItemIds,
  } satisfies IEcommercePlatformShipmentItem.ICreate;
  await TestValidator.error(
    "rejects adding already-shipped items to second shipment",
    async () => {
      await api.functional.ecommercePlatform.seller.shipments.items.create(
        sellerConnection,
        {
          shipmentId: shipment2.id,
          body: addItemsBody,
        },
      );
    },
  );
}

