    tags.Minimum<1> &
    tags.Maximum<5> = 5;
  const filteredByNewRating =
    await api.functional.ecommercePlatform.admin.snapshot_reviews.index(
      adminConnection,
      {
        body: {
          new_rating: newRating,
          page: 1,
          limit: 10,
