      "created_at timestamp exists",
      request.created_at !== undefined,
    );
    TestValidator.predicate(
      "updated_at timestamp exists",
      request.updated_at !== undefined,
    );
  }
  // 5. Test date-based filtering with created_at_gte and created_at_lte
