  TestValidator.equals(
    "non-existent seller filter data empty",
    emptyFilterResponse.data.length,
    0,
  );
  TestValidator.equals(
    "non-existent seller filter pages is 0",
    emptyFilterResponse.pagination.pages,
    0,
  );
}

