import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { generate_random_ecommerce_platform_admin_categories_create } from "../../../generate/generate_random_ecommerce_platform_admin_categories_create";
import { prepare_random_ecommerce_platform_category } from "../../../prepare/prepare_random_ecommerce_platform_category";

export async function test_api_category_browsing_hierarchy_with_children(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, { body: {} });
  // 2. Create first root category (older)
  const olderRootCategory =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {
        body: {
          name: "Electronics",
          description: "Electronic products and devices",
          parentEcommercePlatformCategoryId: null,
        },
      },
    );
  typia.assert(olderRootCategory);
  // 3. Create second root category (newer) - created after older, so should appear first in browsing
  const newerRootCategory =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {
        body: {
          name: "Clothing",
          description: "Clothing and apparel items",
          parentEcommercePlatformCategoryId: null,
        },
      },
    );
  typia.assert(newerRootCategory);
  // 4. Create subcategory under second root category
  const subcategory =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {
        body: {
          name: "Shirts",
          description: "Various types of shirts",
          parentEcommercePlatformCategoryId: newerRootCategory.id,
        },
      },
    );
  typia.assert(subcategory);
  // 5. Call browsing endpoint to retrieve category hierarchy
  // The SDK type declares IBrowsing (singular) but the endpoint returns a hierarchical array
  // We accept the response and use it based on the actual runtime structure
  const browsingConnection: api.IConnection = { host: connection.host };
  const rawResponse =
    await api.functional.ecommercePlatform.browsing(browsingConnection);
  typia.assert(rawResponse);
  // The browsing endpoint returns all root categories as an array, ordered by created_at DESC
  const categories = rawResponse as unknown as IEcommercePlatformCategory.IBrowsing[];
  // 6. Validate we have at least two root category nodes
  TestValidator.predicate(
    "has at least two root categories",
    categories.length >= 2,
  );
  // 7. Validate root categories are ordered by created_at descending (newer first)
  // Find indices of our created categories
  const clothingIndex = categories.findIndex(
    (c) => c.id === newerRootCategory.id,
  );
  const electronicsIndex = categories.findIndex(
    (c) => c.id === olderRootCategory.id,
  );
  TestValidator.equals("Clothing (newer) index", clothingIndex, 0);
  TestValidator.equals("Electronics (older) index", electronicsIndex, 1);
  // 8. Validate the Clothing category has one child (Shirts subcategory)
  const clothingNode = categories.find((c) => c.id === newerRootCategory.id)!;
  typia.assertGuard(clothingNode);
  TestValidator.predicate(
    "Clothing has one child category",
    clothingNode.children.length === 1,
  );
  // 9. Validate subcategory is correctly nested with matching ID and name
  TestValidator.equals(
    "subcategory ID matches created subcategory",
    clothingNode.children[0].id,
    subcategory.id,
  );
  TestValidator.equals(
    "subcategory name matches",
    clothingNode.children[0].name,
    subcategory.name,
  );
  // 10. Validate subcategory has no children (empty array - max two levels)
  TestValidator.equals(
    "subcategory has no children",
    clothingNode.children[0].children.length,
    0,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommercePlatformAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommercePlatformAdmin";
import type { IEcommercePlatformCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommercePlatformCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { generate_random_ecommerce_platform_admin_categories_create } from "../../../generate/generate_random_ecommerce_platform_admin_categories_create";
import { prepare_random_ecommerce_platform_category } from "../../../prepare/prepare_random_ecommerce_platform_category";

/**
 * Validate that soft-deleted categories are properly excluded from the browsing hierarchy.
 *
 * Tests the complete category lifecycle including creation, cascade deletion, and browsing exclusion. Administrator creates a root category with a subcategory, then soft-deletes the root which triggers cascade deletion of all subcategories. The browsing endpoint must exclude both the deleted root and cascade-deleted subcategory from results, validating that the deleted_at null filter correctly filters inactive categories.
 *
 * This test ensures that cascade deletion works as expected and that the browsing endpoint respects the soft-delete state by only returning categories where deleted_at is null.
 *
 * 1. Administrator registers and authenticates via utility function.
 * 2. Administrator creates a root category without a parent.
 * 3. Administrator creates a subcategory under the root category.
 * 4. Browsing endpoint is queried to verify categories appear in hierarchy.
 * 5. Administrator soft-deletes the root category.
 * 6. Browsing endpoint is queried again to verify exclusion.
 * 7. Validates that deleted root and cascade-deleted child IDs do not appear in browsing results.
 */
export async function test_api_category_browsing_excludes_deleted(
  connection: api.IConnection,
) {
  // 1. Administrator registers and authenticates
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create root category
  const root: IEcommercePlatformCategory =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(root);
  // 3. Create subcategory under root
  const child: IEcommercePlatformCategory =
    await generate_random_ecommerce_platform_admin_categories_create(
      adminConnection,
      {
        body: { parentEcommercePlatformCategoryId: root.id },
      },
    );
  typia.assert(child);
  // Verify distinct IDs for root and child
  TestValidator.notEquals("distinct category IDs", root.id, child.id);
  // 4. Browse before deletion
  const browsingBefore: IEcommercePlatformCategory.IBrowsing =
    await api.functional.ecommercePlatform.browsing(adminConnection);
  typia.assert(browsingBefore);
  // 5. Soft-delete root (should cascade delete subcategory)
  await api.functional.ecommercePlatform.admin.categories.erase(
    adminConnection,
    {
      categoryId: root.id,
    },
  );
  // 6. Browse after deletion
  const browsingAfter: IEcommercePlatformCategory.IBrowsing =
    await api.functional.ecommercePlatform.browsing(adminConnection);
  typia.assert(browsingAfter);
  // 7. Validate excluded from browsing
  TestValidator.predicate(
    "deleted root excluded from browsing",
    browsingAfter.id !== root.id,
  );
  TestValidator.predicate(
    "deleted child excluded from browsing children",
    browsingAfter.children.every((c) => c.id !== child.id && c.id !== root.id),
  );
}

