      typeof record.createdAt === "string" && record.createdAt.length > 0,
    );
    TestValidator.predicate(
      "has order ID",
      typeof record.id === "string" && record.id.length > 0,
    );
    TestValidator.predicate(
      "has order number",
      typeof record.orderNumber === "string" && record.orderNumber.length > 0,
