import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { EcommercePlatformSnapshotVariantOptionTransformer } from "../transformers/EcommercePlatformSnapshotVariantOptionTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getEcommercePlatformSellerProductsProductIdVariantsVariantIdSnapshotsSnapshotIdOptionsOptionId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  variantId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
  optionId: string & tags.Format<"uuid">;
}): Promise<IEcommercePlatformSnapshotVariantOption> {
  // 1. Verify product exists and check seller ownership
  const product =
    await MyGlobal.prisma.ecommerce_platform_products.findUniqueOrThrow({
      where: { id: props.productId },
      select: {
        id: true,
        sellerProfile: {
          select: { seller_id: true },
        },
      },
    });
  if (product.sellerProfile.seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }
  // 2. Verify variant exists and belongs to the product
  const variant =
    await MyGlobal.prisma.ecommerce_platform_product_variants.findUniqueOrThrow(
      {
        where: { id: props.variantId },
        select: {
          id: true,
          ecommerce_platform_product_id: true,
        },
      },
    );
  if (variant.ecommerce_platform_product_id !== props.productId) {
    throw new HttpException("Not Found", 404);
  }
  // 3. Verify snapshot exists with appropriate entity_type
  const snapshot =
    await MyGlobal.prisma.ecommerce_platform_snapshots.findUniqueOrThrow({
      where: { id: props.snapshotId },
      select: {
        id: true,
        entity_type: true,
      },
    });
  if (
    snapshot.entity_type !== "product" &&
    snapshot.entity_type !== "product_variant"
  ) {
    throw new HttpException("Not Found", 404);
  }
  // 4. Verify snapshot_variants record links snapshotId to variantId
  const snapshotVariant =
    await MyGlobal.prisma.ecommerce_platform_snapshot_variants.findFirstOrThrow(
      {
        where: {
          ecommerce_platform_snapshot_id: props.snapshotId,
          ecommerce_platform_product_variant_id: props.variantId,
        },
        select: { id: true },
      },
    );
  // 5. Retrieve the option record and transform
  const record =
    await MyGlobal.prisma.ecommerce_platform_snapshot_variant_options.findFirstOrThrow(
      {
        ...EcommercePlatformSnapshotVariantOptionTransformer.select(),
        where: {
          id: props.optionId,
          ecommerce_platform_snapshot_variant_id: snapshotVariant.id,
        },
      },
    );
  return await EcommercePlatformSnapshotVariantOptionTransformer.transform(
    record,
  );
}

