          body: props.body,
          ecommercePlatformCustomers: { id: props.customer.id },
        }),
        ...EcommercePlatformShoppingCartItemTransformer.select(),
      });
  return await EcommercePlatformShoppingCartItemTransformer.transform(record);
}

