  // Build final where with cursor if present
  const whereInput = isCursorBased
    ? ({
        AND: [baseWhere, { id: { gt: body.cursor } }],
      } satisfies Prisma.ecommerce_platform_snapshot_order_itemsWhereInput)
    : baseWhere;
