export class EcommerceplatformSellerProductsVariantsOptionsController {
  /**
   * Create a new attribute option for a specific product variant.
   *
   * Adds a key-value option pair to the specified product variant, enabling customers to identify the variant by its configuration attributes such as color, size, or material. This operation is available to the authenticated seller who owns the parent product.
   *
   * Variants are identified by their SKU code scoped to their parent product. Each variant can have multiple unique attribute keys (e.g., color, size, material), but duplicate keys are not allowed per variant. For example, a variant may have options (color, Red), (size, Large), and (material, Cotton).
   *
   * The authenticated seller must be the owner of the parent product. Attempting to create an option for an unauthorized product returns a 403 Forbidden error. Creating a duplicate attribute key for the same variant returns a 409 Conflict error.
   *
   * @param connection
   * @param productId UUID of the product that owns the variant. Required to scope the variant lookup within the correct product.
   * @param skuCode SKU code uniquely identifying the variant within its parent product. This is the business identifier for product variants.
   * @param body Attribute key and value defining a single option for the product variant. The attribute_key represents the option category (e.g., color, size, material) and attribute_value represents the specific value (e.g., Red, Large, Cotton). Duplicate keys are not allowed per variant.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Query ecommerce_platform_products to locate the product by the provided productId parameter. Verify the product exists and its deleted_at field is null (not soft-deleted). Validate that the authenticated seller's seller_profile_id matches the product's ecommerce_platform_seller_profile_id; return 403 Forbidden if authorization fails.
