import { patchEcommercePlatformAdminSellerApprovalRequests } from "../../../../providers/patchEcommercePlatformAdminSellerApprovalRequests";
import { putEcommercePlatformAdminSellerApprovalRequestsRequestId } from "../../../../providers/putEcommercePlatformAdminSellerApprovalRequestsRequestId";

@Controller("/ecommercePlatform/admin/seller-approval-requests")
export class EcommerceplatformAdminSeller_approval_requestsController {
  /**
   * Searches seller approval requests filtering by status, date ranges, and seller identity with paginated results optimized for administrative review workflows.
   *
   * This endpoint supports filtering by approval status (pending, approved, or rejected), submission date ranges, and seller identification. The reason field is searchable for rejected requests to find specific rejection keywords.
   *
   * Administrators use this operation to manage the seller onboarding pipeline, review pending applications, track approval decisions, and audit historical rejections.
   *
   * @param connection
   * @param body Search criteria for filtering seller approval requests by status, submission date range, update date range, seller identity, optional reason text matching, and pagination controls including cursor and page size.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Query ecommerce_platform_seller_approval_requests table with filtering support.
   *
   * Filters:
   * - status filter: exact match on status enum values (pending, approved, rejected)
   * - created_at range: filter by submission date range (gte, lte)
   * - updated_at range: filter by last modification date range (gte, lte)
   * - seller_id filter: filter by specific seller UUID
   * - reason filter: text search within reason field
   *
   * Apply pagination with cursor-based approach for large result sets.
   *
   * Return IPageIEcommercePlatformSellerApprovalRequest.ISummary containing:
   * - request identification
   * - seller reference
   * - current approval status
   * - reason field (present when rejected)
   * - created_at and updated_at timestamps
   *
   * Join with ecommerce_platform_sellers table to provide seller context information.
   *
   * Handle empty result sets gracefully when no requests match the filter criteria.
   *
   * Exclude soft-deleted records unless explicitly requested for audit retrieval.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IEcommercePlatformSellerApprovalRequest.IRequest,
  ): Promise<IPageIEcommercePlatformSellerApprovalRequest.ISummary> {
    try {
      return await patchEcommercePlatformAdminSellerApprovalRequests({
        admin,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific seller approval request by its unique identifier.
   *
   * Returns complete seller approval request details including the current approval status (pending, approved, or rejected), any rejection reason provided by administrators when applicable, the associated seller identifier, and all creation/update timestamps. This endpoint is primarily accessed by administrators reviewing pending applications and sellers checking their registration status.
   *
   * @param connection
   * @param requestId UUID of the seller approval request to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Query the ecommerce_platform_seller_approval_requests table by primary key `id` matching the provided requestId parameter. Return the complete entity record with all fields: id, ecommerce_platform_seller_id, status, reason, created_at, updated_at, and deleted_at.
   *
   * Verify the request exists and is not soft-deleted (deleted_at IS NULL). If the record is not found or has been soft-deleted, return HTTP 404 Not Found.
   *
   * Join with ecommerce_platform_sellers table using ecommerce_platform_seller_id to validate the associated seller account exists. The seller email and status can be included in the response for administrative reference.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":requestId")
  public async at(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("requestId")
    requestId: string & tags.Format<"uuid">,
  ): Promise<IEcommercePlatformSellerApprovalRequest> {
    try {
      return await getEcommercePlatformAdminSellerApprovalRequestsRequestId({
        admin,
        requestId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update the approval status of a seller approval request. Administrators can approve or reject pending seller registration applications.
   *
   * Only requests with 'pending' status can be updated. When approving, the seller gains full selling privileges. When rejecting, a rejection reason must be provided and is visible to the seller.
   *
   * @param connection
   * @param requestId Unique identifier of the seller approval request to update (global scope)
   * @param body Approval decision containing new status ('approved' or 'rejected') and optional rejection reason (required when rejecting).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification 1. Validate requestId exists and belongs to ecommerce_platform_seller_approval_requests table
   * 2. Verify request status is 'pending' - reject with 400 if status is already 'approved' or 'rejected'
   * 3. If new status is 'approved':
   *    - Set status to 'approved'
   *    - Clear/nullify reason field
   *    - Grant seller selling privileges
   * 4. If new status is 'rejected':
   *    - Validate reason is provided and non-empty
   *    - Set status to 'rejected'
   *    - Set reason to provided value
   * 5. Update updated_at timestamp
   * 6. Return updated seller approval request entity
